CREATE TABLE cmdb_ire_conflicts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, tenant_id BIGINT UNSIGNED NOT NULL, source_id BIGINT UNSIGNED NOT NULL, run_id BIGINT UNSIGNED NULL, observation_id BIGINT UNSIGNED NULL, conflict_type ENUM('DUPLICATE','IDENTITY','FIELD','REFERENCE','MERGE') NOT NULL, state ENUM('OPEN','RESOLVED','DISMISSED') NOT NULL DEFAULT 'OPEN', source_key VARCHAR(255) NOT NULL, candidate_ci_ids JSON NOT NULL, value_diff JSON NOT NULL, reference_diff JSON NOT NULL, resolution_note VARCHAR(1000) NOT NULL DEFAULT '', resolved_by BIGINT UNSIGNED NULL, resolved_at DATETIME(6) NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE KEY cmdb_ire_conflict_tenant_id(tenant_id,id), UNIQUE KEY cmdb_ire_conflict_observation_key(tenant_id,observation_id,conflict_type), KEY cmdb_ire_conflict_queue(tenant_id,state,id), KEY cmdb_ire_conflict_source(tenant_id,source_id,state,id), CONSTRAINT cmdb_ire_conflict_source FOREIGN KEY(tenant_id,source_id) REFERENCES cmdb_ire_sources(tenant_id,id), CONSTRAINT cmdb_ire_conflict_run FOREIGN KEY(tenant_id,run_id) REFERENCES cmdb_ire_runs(tenant_id,id), CONSTRAINT cmdb_ire_conflict_observation FOREIGN KEY(tenant_id,observation_id) REFERENCES cmdb_ire_observations(tenant_id,id), CONSTRAINT cmdb_ire_conflict_resolver FOREIGN KEY(resolved_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
